// ============================================================================
// WF-01 -- Normalize
// Maps inbound webhook payloads (GHL workflow webhooks and Close webhooks)
// into the canonical message consumed by the agent service:
//
//   {
//     message_id: string,            // stable id of the inbound message
//     channel:    "sms" | "email",   // Phase 1 = sms; email is Phase 2
//     source:     "close" | "ghl",   // which system delivered the event
//     contact_id: string,            // GHL contact id (ghl only; "" if unknown)
//     sender:     string,            // phone number (sms) or email address
//     body:       string,            // message text
//     timestamp:  string             // ISO-8601 of when the message arrived
//   }
//
// SHAPE STATUS: DEFENSIVE, STILL UNVERIFIED. GHL's workflow Webhook action
// POSTs whatever custom data was configured on the action -- ours has none
// configured yet, so the real default body shape is UNKNOWN until the first
// real execution lands. Every path marked [VERIFY] is therefore tried as a
// *candidate*: the mapper takes the first non-empty value across all plausible
// paths, and the main gate below REFUSES to emit a canonical message unless
// a body AND an identity (sender phone/email or GHL contact_id) were actually
// found. Unknown/incomplete shapes route to output 1 (the anomaly sink) --
// "doing nothing is the default" applies to parsing too. When the first real
// execution arrives, tighten the mappers to its exact paths and re-verify.
//
// Contract:
//   - Output 0 (main): one canonical message item per recognised payload.
//   - Output 1 (error): payloads this node could not recognise, routed to
//     the error sink for logging. NEVER throws -- unknown shapes land on
//     output 1, never crash the workflow.
// ============================================================================

const items = $input.all();
const ok = [];   // output 0: canonical messages
const bad = [];  // output 1: unknown shapes

// First non-empty string wins. Present-but-blank values are skipped so an
// empty key never shadows a populated one further down the candidate list.
function pick(...vals) {
  for (const v of vals) {
    if (v === null || v === undefined) continue;
    const s = String(v).trim();
    if (s) return s;
  }
  return '';
}

// ---- Shape detectors -------------------------------------------------------
function isCloseWebhook(p) {
  // Close webhooks wrap the payload as { event, object_type, data, ... }. [VERIFY]
  if (!p || typeof p !== 'object') return false;
  return (typeof p.event === 'string' && p.data && typeof p.data === 'object')
      || typeof p.object_type === 'string';
}

function isGHLWorkflowWebhook(p) {
  // GHL workflow webhooks (e.g. the "Customer Replied" workflow) POST the
  // contact object plus message/trigger fields -- exact keys [VERIFY].
  if (!p || typeof p !== 'object') return false;
  return (p.contact && typeof p.contact === 'object')
      || typeof p.contact_id === 'string'
      || typeof p.contactId === 'string'
      || (p.message && typeof p.message === 'object')
      || (p.eventData && p.eventData.source === 'workflow');
}

// ---- Mappers ----------------------------------------------------------------
function mapGHL(p) {
  const contact = (p.contact && typeof p.contact === 'object') ? p.contact : {};
  const msg = (p.message && typeof p.message === 'object') ? p.message : {};
  const rawType = pick(msg.type, msg.channel, msg.reply_channel,
                       p.channel, p.reply_channel, p.type);            // [VERIFY]
  const channel = /email/i.test(rawType) ? 'email' : 'sms'; // default sms; Phase 1 scope. [VERIFY]
  return {
    message_id: pick(msg.id, p.message_id, p.messageId, p.event_id, p.eventId, p.id), // [VERIFY]
    channel,
    source: 'ghl',
    contact_id: pick(contact.id, p.contact_id, p.contactId), // [VERIFY] feeds ghl.send_sms
    sender: pick(contact.phone, contact.phone_number, p.phone, p.phone_number,
                 msg.from, msg.phone),                       // [VERIFY]
    body: pick(msg.body, msg.text, msg.message, p.body, p.text,
               p.message_body, p.messageText),                // [VERIFY]
    timestamp: pick(msg.date_added, msg.created_at, msg.createdAt, msg.date_created,
                    p.timestamp, p.date_created, p.createdAt,
                    new Date().toISOString()),                // [VERIFY]
  };
}

function mapClose(p) {
  const data = p.data || {};                        // [VERIFY] payload wrapped in `data`?
  const rawType = String(data.type || data.activity_type || '').toUpperCase(); // [VERIFY]
  const channel = rawType === 'EMAIL' ? 'email' : 'sms'; // [VERIFY]
  const contact = data.contact || {};               // [VERIFY] contact nested under data?
  const phones = Array.isArray(contact.phones) ? contact.phones : []; // [VERIFY]
  const firstPhone = (phones[0] && phones[0].phone) || '';
  return {
    message_id: String(data.id || p.id || ''),      // [VERIFY]
    channel,
    source: 'close',
    sender: channel === 'email'
      ? String(contact.email || data.sender || '')  // [VERIFY]
      : String(firstPhone || contact.phone || data.sender || ''), // [VERIFY]
    body: String(data.text || data.body || ''),     // [VERIFY]
    timestamp: String(data.date_created || data.created_at || p.date_created || new Date().toISOString()), // [VERIFY]
  };
}

// ---- Main -------------------------------------------------------------------
for (const item of items) {
  const p = item.json;
  let canonical = null;
  let shape = 'unknown';

  if (isCloseWebhook(p)) { shape = 'close'; canonical = mapClose(p); }
  else if (isGHLWorkflowWebhook(p)) { shape = 'ghl'; canonical = mapGHL(p); }

  const missing = [];
  if (!canonical) {
    missing.push('unrecognized_shape');
  } else {
    if (!canonical.body) missing.push('body');
    if (!canonical.sender && !canonical.contact_id) missing.push('sender/contact_id');
  }

  if (canonical && missing.length === 0) {
    ok.push({ json: canonical });
  } else {
    bad.push({ json: {
      error: 'unknown_or_incomplete_shape',
      detected_shape: shape,
      missing,
      hint: 'Compare against n8n/fixtures/*.json and update the mappers above.',
      raw: p,
    }});
  }
}

// Two outputs: [canonical messages, unknown shapes]. Never throws.
return [ok, bad];
